<template><div class="container-page py-10"><NuxtLink to="/admin/blog" class="font-semibold text-primary-700">← Blog</NuxtLink><h1 class="mt-3 text-3xl">Write Article</h1><form class="card mt-7 space-y-5 p-6" @submit.prevent="save"><div><label class="label">Article title *</label><input v-model="form.title" class="input" required @input="syncSlug"/></div><div><label class="label">URL slug *</label><input v-model="form.slug" class="input" required/></div><div><label class="label">Excerpt *</label><textarea v-model="form.excerpt" class="input min-h-20" maxlength="300" required/></div><div><label class="label">Article content *</label><textarea v-model="form.content" class="input min-h-96" required placeholder="Write useful, original content. Separate paragraphs with blank lines."/></div><div class="grid gap-5 md:grid-cols-2"><div><label class="label">SEO title</label><input v-model="form.meta_title" class="input" maxlength="65"/><p class="mt-1 text-xs text-neutral-500">{{form.meta_title.length}}/65</p></div><div><label class="label">Meta description</label><textarea v-model="form.meta_description" class="input min-h-20" maxlength="160"/><p class="mt-1 text-xs text-neutral-500">{{form.meta_description.length}}/160</p></div><div><label class="label">Tags (comma separated)</label><input v-model="tagInput" class="input" placeholder="Ibadan, land buying, property guide"/></div><div><label class="label">Featured image URL</label><input v-model="form.featured_image" class="input" type="url"/></div></div><label class="flex items-center gap-2"><input v-model="form.published" type="checkbox"/> Publish immediately</label><p v-if="error" class="rounded-lg bg-error-50 p-3 text-error-800">{{error}}</p><button class="btn-primary" :disabled="busy">{{busy?'Saving…':form.published?'Publish Article':'Save Draft'}}</button></form></div></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin-auth'});const busy=ref(false),error=ref(''),tagInput=ref('');const form=reactive({title:'',slug:'',excerpt:'',content:'',author:'Lexshield Properties',featured_image:'',meta_title:'',meta_description:'',published:false});function syncSlug(){form.slug=form.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!form.meta_title)form.meta_title=form.title}async function save(){busy.value=true;error.value='';try{const{error:e}=await useSupabase().from('blog_posts').insert({...form,featured_image:form.featured_image||null,tags:tagInput.value.split(',').map(x=>x.trim()).filter(Boolean),published_at:form.published?new Date().toISOString().slice(0,10):null});if(e)throw e;await navigateTo('/admin/blog')}catch(e:any){error.value=e.message||'Could not save article'}finally{busy.value=false}}useSeoMeta({title:'New Article | Admin',robots:'noindex,nofollow'})</script>
